(function(){
  const today=()=>new Date().toISOString().slice(0,10);
  const filename=type=>`ecofood-atu-${today()}.${type}`;
  const totalKg=reports=>reports.reduce((sum,item)=>sum+Number(item.kg||0),0);
  const period=reports=>{const dates=reports.map(item=>item.date).filter(Boolean).sort();return dates.length?`${dates[0]} — ${dates.at(-1)}`:'—'};
  const groups=(reports,key,labels)=>Object.entries(key==='org'?reports.reduce((acc,item)=>{const label=labels.catalog(item.org);acc[label]=(acc[label]||0)+Number(item.kg||0);return acc},{}):reports.flatMap(report=>report.entries?.length?report.entries:[{type:report.type,quantity:report.kg,unit:'kg'}]).reduce((acc,item)=>{if(item.unit&&item.unit!=='kg')return acc;const label=labels.catalog(item.type);acc[label]=(acc[label]||0)+Number(item.quantity??item.kg??0);return acc},{})).sort((a,b)=>b[1]-a[1]);
  const co2Total=(reports,labels)=>reports.flatMap(report=>report.entries?.length?report.entries:[{type:report.type,quantity:report.kg,unit:'kg',disposal:report.disposal}]).reduce((sum,item)=>{const type=(labels.wasteTypes||[]).find(entry=>entry.name===item.type);if(!type)return sum;const mass=Number(item.quantity??item.kg??0)*(item.unit==='l'?.92:1),method=(labels.disposalCatalog||[]).find(entry=>entry.name===item.disposal),actual=method?.code==='TBO'?Number(type.co2Tbo):Number(method?.co2Factor);if(!Number.isFinite(actual)||!Number.isFinite(Number(type.co2Tbo)))return sum;return sum+mass/1000*Math.max(0,Number(type.co2Tbo)-actual)},0);
  function rows(reports,labels){return reports.flatMap(report=>(report.entries?.length?report.entries:[{date:report.date,type:report.type,quantity:report.kg,unit:'kg',disposal:'—',source:report.source,reason:report.reason}]).map((item,index)=>({[labels.id]:`${report.id}-${index+1}`,[labels.organization]:labels.catalog(report.org),[labels.date]:item.date,[labels.category]:labels.catalog(item.type),[labels.quantity]:Number(item.quantity??item.kg??0),[labels.unit]:item.unit||'kg',[labels.disposal]:item.disposal||'—',[labels.reason]:labels.reason(item.reason),[labels.status]:labels.status(report.status)})))}
  function autoColumns(sheet,widths){sheet['!cols']=widths.map(wch=>({wch}))}
  function exportXlsx(reports,labels){
    if(!window.XLSX)throw new Error('XLSX_NOT_READY');
    const total=totalKg(reports),co2=co2Total(reports,labels),book=XLSX.utils.book_new();
    const summary=XLSX.utils.aoa_to_sheet([[labels.quarterlyTitle],[],[labels.period,period(reports)],[labels.generated,today()],[labels.prepared,labels.preparedBy||'—'],[],[labels.summary],[labels.records,reports.length],[labels.total,Number(total.toFixed(1))],[labels.co2,Number(co2.toFixed(1))],[],[labels.methodNote]]);
    summary['!merges']=[XLSX.utils.decode_range('A1:D1'),XLSX.utils.decode_range('A7:D7'),XLSX.utils.decode_range('A12:D14')];autoColumns(summary,[30,28,18,18]);
    const orgData=[[labels.organization,labels.weight,labels.share],...groups(reports,'org',labels).map(([name,kg])=>[name,Number(kg.toFixed(1)),total?`${(kg/total*100).toFixed(1)}%`:'0%'])];
    const typeData=[[labels.category,labels.weight,labels.share],...groups(reports,'type',labels).map(([name,kg])=>[name,Number(kg.toFixed(1)),total?`${(kg/total*100).toFixed(1)}%`:'0%'])];
    const orgSheet=XLSX.utils.aoa_to_sheet(orgData),typeSheet=XLSX.utils.aoa_to_sheet(typeData),registry=XLSX.utils.json_to_sheet(rows(reports,labels));
    autoColumns(orgSheet,[34,16,14]);autoColumns(typeSheet,[30,16,14]);autoColumns(registry,[17,34,13,32,14,10,26,24,18]);
    XLSX.utils.book_append_sheet(book,summary,'Summary');XLSX.utils.book_append_sheet(book,orgSheet,'Organizations');XLSX.utils.book_append_sheet(book,typeSheet,'Categories');XLSX.utils.book_append_sheet(book,registry,'Registry');XLSX.writeFile(book,filename('xlsx'),{compression:true});
  }
  let fontPromise,logoPromise;
  async function loadFont(doc){if(!fontPromise)fontPromise=fetch('assets/NotoSans.ttf').then(response=>{if(response.ok)return response.arrayBuffer();return fetch('https://raw.githubusercontent.com/google/fonts/main/ofl/notosans/NotoSans%5Bwdth,wght%5D.ttf').then(fallback=>{if(!fallback.ok)throw new Error('FONT_NOT_FOUND');return fallback.arrayBuffer()})}).then(buffer=>{const bytes=new Uint8Array(buffer);let binary='';for(let index=0;index<bytes.length;index+=0x8000)binary+=String.fromCharCode(...bytes.subarray(index,index+0x8000));return btoa(binary)});doc.addFileToVFS('NotoSans.ttf',await fontPromise);doc.addFont('NotoSans.ttf','NotoSans','normal');doc.setFont('NotoSans')}
  async function loadLogo(){if(!logoPromise)logoPromise=fetch('assets/ecofood-atu-transparent.png').then(response=>response.ok?response.blob():null).then(blob=>blob&&new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.readAsDataURL(blob)})).catch(()=>null);return logoPromise}
  const wrap=(doc,value,width)=>doc.splitTextToSize(String(value??''),width);
  function heading(doc,title,y){doc.setTextColor(12,55,112);doc.setFontSize(13);doc.text(title,14,y);doc.setDrawColor(246,193,48);doc.setLineWidth(.8);doc.line(14,y+3,282,y+3)}
  function breakdown(doc,title,data,total,y){heading(doc,title,y);y+=9;doc.setFillColor(12,55,112);doc.rect(14,y,268,8,'F');doc.setTextColor(255);doc.setFontSize(8);doc.text(title,17,y+5.5);doc.text('kg',232,y+5.5);doc.text('%',270,y+5.5);y+=8;data.slice(0,8).forEach(([name,kg],index)=>{if(index%2===0){doc.setFillColor(243,247,251);doc.rect(14,y,268,8,'F')}doc.setTextColor(23,39,64);doc.text(wrap(doc,name,195).slice(0,1),17,y+5.5);doc.text(kg.toFixed(1),232,y+5.5);doc.text(total?(kg/total*100).toFixed(1):'0.0',270,y+5.5);y+=8});return y}
  async function exportPdf(reports,labels){
    if(!window.jspdf?.jsPDF)throw new Error('PDF_NOT_READY');
    const {jsPDF}=window.jspdf,doc=new jsPDF({orientation:'landscape',unit:'mm',format:'a4',compress:true});await loadFont(doc);
    const total=totalKg(reports),co2=co2Total(reports,labels),logo=await loadLogo();doc.setProperties({title:labels.quarterlyTitle,subject:labels.period,author:labels.preparedBy||'EcoFood ATU',creator:'EcoFood ATU'});
    doc.setFillColor(8,46,102);doc.rect(0,0,297,38,'F');if(logo)try{doc.addImage(logo,'PNG',14,8,48,18,undefined,'FAST')}catch{}
    doc.setTextColor(255);doc.setFontSize(19);doc.text(labels.quarterlyTitle,logo?69:14,17);doc.setFontSize(9);doc.text(`${labels.period}: ${period(reports)}   ·   ${labels.generated}: ${today()}`,logo?69:14,26);
    const cards=[[labels.records,String(reports.length)],[labels.total,`${total.toFixed(1)} kg`],[labels.co2,`${co2.toFixed(1)} kg CO₂e`]];cards.forEach(([label,value],index)=>{const x=14+index*91;doc.setFillColor(index===1?236:244,index===1?249:247,index===1?241:251);doc.roundedRect(x,47,84,26,3,3,'F');doc.setTextColor(76,89,106);doc.setFontSize(8);doc.text(label,x+6,56);doc.setTextColor(10,55,111);doc.setFontSize(16);doc.text(value,x+6,67)});
    let y=86;y=breakdown(doc,labels.organizationBreakdown,groups(reports,'org',labels),total,y)+11;y=breakdown(doc,labels.categoryBreakdown,groups(reports,'type',labels),total,y)+10;
    doc.setTextColor(85,96,112);doc.setFontSize(7.5);doc.text(wrap(doc,labels.methodNote,268),14,Math.min(y,181));
    doc.addPage('a4','landscape');heading(doc,labels.detailedRegistry,14);let tableY=21;const columns=[labels.id,labels.organization,labels.date,labels.category,labels.quantity,labels.unit,labels.disposal,labels.reason,labels.status],widths=[20,43,22,34,18,10,35,36,24],left=10,rowHeight=9;
    const tableHeader=()=>{doc.setFillColor(12,55,112);doc.rect(left,tableY,262,rowHeight,'F');doc.setTextColor(255);doc.setFontSize(7.5);let x=left+2;columns.forEach((label,index)=>{doc.text(wrap(doc,label,widths[index]-4).slice(0,2),x,tableY+5.7);x+=widths[index]});tableY+=rowHeight};tableHeader();
    rows(reports,labels).forEach((item,index)=>{if(tableY+rowHeight>184){doc.addPage('a4','landscape');tableY=14;tableHeader()}if(index%2===0){doc.setFillColor(244,248,252);doc.rect(left,tableY,262,rowHeight,'F')}doc.setTextColor(20,37,62);doc.setFontSize(7);let x=left+2;Object.values(item).forEach((value,column)=>{doc.text(wrap(doc,value,widths[column]-4).slice(0,2),x,tableY+5.7);x+=widths[column]});tableY+=rowHeight});
    if(tableY>158){doc.addPage('a4','landscape');tableY=30}else tableY+=20;[[labels.prepared,labels.preparedBy||''],[labels.reviewed,''],[labels.approvedBy,'']].forEach(([label,name],index)=>{const x=14+index*91;doc.setTextColor(68,81,99);doc.setFontSize(8);doc.text(label,x,tableY);doc.setDrawColor(115,126,140);doc.line(x,tableY+12,x+74,tableY+12);if(name)doc.text(wrap(doc,name,70).slice(0,1),x,tableY+9);doc.text(labels.signature,x,tableY+18)});
    const pages=doc.getNumberOfPages();for(let page=1;page<=pages;page++){doc.setPage(page);doc.setDrawColor(213,220,230);doc.line(14,198,283,198);doc.setTextColor(96,108,124);doc.setFontSize(7);doc.text('EcoFood ATU',14,204);doc.text(`${page} / ${pages}`,283,204,{align:'right'})}doc.save(filename('pdf'));
  }
  window.EcoFoodExports={exportXlsx,exportPdf};
})();
